CREATE TYPE public.app_role AS ENUM ('admin','principal','teacher','student');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
GRANT UPDATE(display_name) ON public.profiles TO authenticated;
REVOKE UPDATE ON public.profiles FROM authenticated;
GRANT UPDATE(display_name) ON public.profiles TO authenticated;
CREATE POLICY edit_name ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_school_role(wanted public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(auth.jwt()->>'aal'='aal2',false) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role=wanted AND active) $$;
REVOKE ALL ON FUNCTION public.has_school_role(public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_school_role(public.app_role) TO authenticated;
CREATE POLICY admin_roles ON public.user_roles FOR SELECT TO authenticated USING(public.has_school_role('admin'));
CREATE POLICY admin_profiles ON public.profiles FOR SELECT TO authenticated USING(public.has_school_role('admin') OR public.has_school_role('principal'));
CREATE TABLE public.role_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, requested_role public.app_role NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, UNIQUE(user_id,requested_role));
GRANT SELECT, INSERT ON public.role_requests TO authenticated; GRANT ALL ON public.role_requests TO service_role;
ALTER TABLE public.role_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_requests ON public.role_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_school_role('admin'));
CREATE POLICY request_access ON public.role_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND reviewed_at IS NULL AND requested_role!='admin');
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, target_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_audit ON public.audit_logs FOR SELECT TO authenticated USING(public.has_school_role('admin'));
CREATE FUNCTION public.create_school_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name,email) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100),coalesce(NEW.email,'')); IF NEW.raw_user_meta_data->>'requested_role' IN ('student','teacher','principal') THEN INSERT INTO public.role_requests(user_id,requested_role) VALUES(NEW.id,(NEW.raw_user_meta_data->>'requested_role')::public.app_role); END IF; RETURN NEW; END $$;
CREATE TRIGGER school_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_school_profile();
CREATE FUNCTION public.review_role_request(request_id uuid, approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.role_requests; BEGIN IF NOT public.has_school_role('admin') THEN RAISE EXCEPTION 'Admin access and two-step verification required'; END IF; SELECT * INTO r FROM public.role_requests WHERE id=request_id FOR UPDATE; IF NOT FOUND OR r.status!='pending' OR r.requested_role='admin' THEN RAISE EXCEPTION 'Request cannot be reviewed'; END IF; IF approve THEN IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=r.user_id AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Email must be confirmed first'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(r.user_id,r.requested_role) ON CONFLICT(user_id,role) DO UPDATE SET active=true; END IF; UPDATE public.role_requests SET status=CASE WHEN approve THEN 'approved' ELSE 'rejected' END, reviewed_at=now() WHERE id=request_id; INSERT INTO public.audit_logs(actor_id,action,target_id) VALUES(auth.uid(),CASE WHEN approve THEN 'role_approved' ELSE 'role_rejected' END,r.user_id); END $$;
REVOKE ALL ON FUNCTION public.review_role_request(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_role_request(uuid,boolean) TO authenticated;
CREATE TABLE public.admission_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), student_name text NOT NULL, guardian_name text NOT NULL, email text NOT NULL, phone text NOT NULL, entry_year text NOT NULL, notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','reviewing','accepted','declined')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.admission_applications TO authenticated; GRANT ALL ON public.admission_applications TO service_role;
ALTER TABLE public.admission_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY submit_application ON public.admission_applications FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='submitted');
CREATE POLICY read_application ON public.admission_applications FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_school_role('admin'));
CREATE TABLE public.contact_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), name text NOT NULL, email text NOT NULL, subject text NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT, SELECT ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY send_message ON public.contact_messages FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY read_message ON public.contact_messages FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_school_role('admin'));
CREATE INDEX role_requests_pending ON public.role_requests(status,created_at);
CREATE INDEX applications_owner ON public.admission_applications(user_id);
CREATE INDEX messages_owner ON public.contact_messages(user_id);